from collections import defaultdict
from functools import lru_cache
H,W=holes.shape
holebits=sum(1 << (r*W+c) for r,c in holes_pts)
def trim_arr(arr):
    # trims padding color8; objects don't have 8 inside except none
    pts=np.argwhere(arr!=8)
    r0,c0=pts.min(0);r1,c1=pts.max(0)
    return arr[r0:r1+1,c0:c1+1]
def transform_arr(arr, rot=0, reflect=False):
    a=arr.copy()
    if reflect: a=np.fliplr(a)
    return trim_arr(np.rot90(a,rot))
def encode_shape(arr):
    pts=np.argwhere(arr!=8)
    mask=0
    for r,c in pts: mask |= 1 << (int(r)*W+int(c))
    return mask

def gen_placements(allow_rot=True, allow_ref=False):
    orient_by_piece=[]
    for p in pieces:
        orients=[]
        transforms=[(0,False)] if not allow_rot else [(r,False) for r in range(4)]
        if allow_ref: transforms += [(r,True) for r in range(4)]
        seen=set()
        for rot,ref in transforms:
            arr=transform_arr(p['arr'],rot,ref)
            # retain color orientations if same color array duplicate not needed
            key=tuple(map(tuple,arr.tolist()))
            if key in seen: continue
            seen.add(key)
            orients.append(arr)
        orient_by_piece.append(orients)
    places=[]
    for i,orients in enumerate(orient_by_piece):
        for oi,arr in enumerate(orients):
            h,w=arr.shape
            pmask=encode_shape(arr)
            for r0 in range(H-h+1):
              for c0 in range(W-w+1):
                bits=0
                for r,c in np.argwhere(arr!=8):
                    bits |= 1 << ((r0+int(r))*W+c0+int(c))
                if bits & holebits == bits:
                    places.append((i,oi,r0,c0,bits,arr))
    return places,orient_by_piece

places,orients=gen_placements(allow_rot=False)
